def metric(data: pd.DataFrame) -> float:
    target_profile = (0, 1, 1, 0, 0)
    matches = 0
    total = 0
    for _, row in data.iterrows():
        a = tuple(row['option_a_ratings'])
        b = tuple(row['option_b_ratings'])
        if a == target_profile:
            total += 1
            if row['response'] == 0:
                matches += 1
        elif b == target_profile:
            total += 1
            if row['response'] == 1:
                matches += 1
    if total == 0:
        return 0.5
    return float(matches / total)

